// Package brand holds the app's logo as window icons: one 256 px PNG per
// season (icons/<id>.png, generated by scripts/brand/build.ts) and the code that
// sets the main window's icon. The ids are the SeasonId of src/lib/brand/season.ts.
//
// The icon of the pinned taskbar button and of the shortcuts is the exe's icon
// resource (the default logo): no running code can change it, so seasons only
// reach the title bar and the Alt+Tab / taskbar button of the running window.
package brand

import (
	"embed"
	"errors"
	"slices"
	"strings"
)

//go:embed icons/*.png
var iconFiles embed.FS

// ErrUnknownID is an id that is not one of the embedded icons.
var ErrUnknownID = errors.New("logo inconnu")

// ErrNoWindow is a window icon asked for before the window exists.
var ErrNoWindow = errors.New("fenêtre indisponible")

// ids is the sorted list of embedded icon ids.
var ids = func() []string {
	entries, err := iconFiles.ReadDir("icons")
	if err != nil {
		panic(err)
	}
	var out []string
	for _, e := range entries {
		if name, ok := strings.CutSuffix(e.Name(), ".png"); ok {
			out = append(out, name)
		}
	}
	slices.Sort(out)
	return out
}()

// IDs are the ids of the embedded icons, sorted.
func IDs() []string { return slices.Clone(ids) }

// Valid reports whether id is one of the embedded icons.
func Valid(id string) bool { return slices.Contains(ids, id) }

// PNG is the 256 px icon of id. The path is never built from an unknown id.
func PNG(id string) ([]byte, error) {
	if !Valid(id) {
		return nil, ErrUnknownID
	}
	return iconFiles.ReadFile("icons/" + id + ".png")
}
